let dict: Set<string> | null = null;

/** Whether `word` (exactly five A–Z letters, any case) is in the dictionary. */
export function inDictionary(word: string): boolean {
  if (!dict) {
    dict = new Set();
    for (let i = 0; i < PACKED.length; i += 5) dict.add(PACKED.slice(i, i + 5));
  }
  return dict.has(word.toUpperCase());
}
